<?php
function enrolmentLink(array $admin,int $staff):string{global $config;attRequire($admin['role']==='admin');attRequire(str_starts_with($config['url'],'https://'),'Set the HTTPS application URL before issuing phone enrolment links.');$u=one('SELECT * FROM users WHERE id=?',[$staff]);attRequire($u&&teaching($u),'Enable attendance for this staff entry first.');attLock();q('UPDATE tutor_enrolment_links SET used_at=? WHERE staff_id=? AND used_at IS NULL',[time(),$staff]);$raw=bin2hex(random_bytes(32));q('INSERT INTO tutor_enrolment_links(staff_id,token_hash,expires_at,created_by,created_at) VALUES(?,?,?,?,?)',[$staff,hash('sha256',$raw),time()+3600,$admin['id'],now()]);attAudit((int)$admin['id'],'Phone enrolment issued',$staff);return rtrim($config['url'],'/').'/enrol-phone.php?t='.$raw;}
function consumeEnrolment(string $raw,string $name):string{attRequire((bool)preg_match('/^[a-f0-9]{64}$/',$raw),'Invalid enrolment link.');attRequire(trim($name)!==''&&mb_strlen($name)<=160,'Enter a phone/browser name.');attLock();$link=one('SELECT * FROM tutor_enrolment_links WHERE token_hash=? AND used_at IS NULL AND expires_at>?',[hash('sha256',$raw),time()]);attRequire((bool)$link,'Enrolment link expired or already used. Ask Admin for a new link.');$staff=one('SELECT * FROM users WHERE id=?',[$link['staff_id']]);attRequire($staff&&teaching($staff),'Staff attendance access is no longer active.');q('UPDATE tutor_enrolment_links SET used_at=? WHERE id=?',[time(),$link['id']]);q('UPDATE tutor_registered_devices SET active=0,revoked_at=? WHERE staff_id=? AND active=1',[now(),$staff['id']]);$token=bin2hex(random_bytes(32));q('INSERT INTO tutor_registered_devices(staff_id,token_hash,device_name,user_agent,registered_at,created_ip) VALUES(?,?,?,?,?,?)',[$staff['id'],hash('sha256',$token),$name,substr($_SERVER['HTTP_USER_AGENT']??'',0,500),now(),$_SERVER['REMOTE_ADDR']??'CLI']);attAudit((int)$staff['id'],'Phone enrolled without login',(int)db()->lastInsertId());return $token;}
